import{_ as c,r as s,o as p,c as r,e as n,a as t,s as e}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Столбцы списка - October CMS - 3.x","titleTemplate":false,"description":"Узнайте, как определять столбцы в структуре списка.","frontmatter":{"subtitle":"Узнайте, как определять столбцы в структуре списка."},"headers":[{"level":2,"title":"Доступные столбцы","slug":"доступные-столбцы","link":"#доступные-столбцы","children":[]},{"level":2,"title":"Свойства столбцов","slug":"своиства-столбцов","link":"#своиства-столбцов","children":[{"level":3,"title":"Пользовательский выбор значения","slug":"пользовательскии-выбор-значения","link":"#пользовательскии-выбор-значения","children":[]},{"level":3,"title":"Вложенный выбор столбцов","slug":"вложенныи-выбор-столбцов","link":"#вложенныи-выбор-столбцов","children":[]},{"level":3,"title":"Прямой SQL-выбор","slug":"прямои-sql-выбор","link":"#прямои-sql-выбор","children":[]},{"level":3,"title":"Выбор связанного столбца","slug":"выбор-связанного-столбца","link":"#выбор-связанного-столбца","children":[]},{"level":3,"title":"Подсказка","slug":"подсказка","link":"#подсказка","children":[]}]}],"relativePath":"3.x/ru/element/list-columns.md","filePath":"3.x/ru/element/list-columns.md"}'),d={name:"3.x/ru/element/list-columns.md"};function u(i,a,k,m,g,h){const l=s("pre-heading"),o=s("post-heading");return p(),r("div",null,[n(l),a[0]||(a[0]=t("h1",null,"Столбцы списка",-1)),n(o),a[1]||(a[1]=e(`<p>Столбцы списка — это определения столбцов, используемые списками. На них ссылаются следующие области.</p><ul><li><a href="./../extend/lists/list-controller.html">Контроллер списков</a></li><li><a href="./../extend/forms/relation-controller.html">Контроллер отношений</a></li></ul><p>Все столбцы списка идентифицируются по их индивидуальному свойству <strong>type</strong>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">columns</span><span class="token punctuation">:</span>
    <span class="token key atrule">mycolumn</span><span class="token punctuation">:</span>
        <span class="token key atrule">type</span><span class="token punctuation">:</span> number
        <span class="token comment"># ...</span>
</code></pre></div><h2 id="доступные-столбцы"><a href="#доступные-столбцы" class="header-anchor">#</a> Доступные столбцы</h2><p>Доступны следующие столбцы списка:</p>`,6)),a[2]||(a[2]=t("div",{class:"content-list-p",markdown:"1"},[t("p",null,[t("a",{href:"./lists/column-text.html"},"Text"),t("a",{href:"./lists/column-number.html"},"Number"),t("a",{href:"./lists/column-image.html"},"Image"),t("a",{href:"./lists/column-switch.html"},"Switch"),t("a",{href:"./lists/column-summary.html"},"Summary"),t("a",{href:"./lists/column-datetime.html"},"Date & Time"),t("a",{href:"./lists/column-selectable.html"},"Selectable"),t("a",{href:"./lists/column-linkage.html"},"Linkage"),t("a",{href:"./lists/column-partial.html"},"Partial"),t("a",{href:"./lists/column-colorpicker.html"},"Color Picker"),t("a",{href:"./lists/column-currency.html"},"Currency")])],-1)),a[3]||(a[3]=e(`<h2 id="своиства-столбцов"><a href="#своиства-столбцов" class="header-anchor">#</a> Свойства столбцов</h2><p>Для каждого столбца можно указать следующие свойства (где применимо):</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>имя при отображении столбца списка пользователю.</td></tr><tr><td><strong>type</strong></td><td>определяет, как должен рендериться этот столбец.</td></tr><tr><td><strong>default</strong></td><td>задаёт значение по умолчанию для столбца, если значение пусто.</td></tr><tr><td><strong>searchable</strong></td><td>включает этот столбец в результаты поиска по списку. По умолчанию: <code>false</code>.</td></tr><tr><td><strong>invisible</strong></td><td>определяет, скрыт ли этот столбец по умолчанию. По умолчанию: <code>false</code>.</td></tr><tr><td><strong>sortable</strong></td><td>определяет, можно ли сортировать по этому столбцу. По умолчанию: <code>true</code>.</td></tr><tr><td><strong>sortableDefault</strong></td><td>определяет, сортируется ли этот столбец по умолчанию. Должно использоваться только на одном сортируемом столбце. Поддерживаемые значения: <code>asc</code>, <code>desc</code>.</td></tr><tr><td><strong>clickable</strong></td><td>если установлено в false, отключает стандартное поведение при клике на столбец. По умолчанию: true.</td></tr><tr><td><strong>select</strong></td><td>определяет пользовательское SQL-выражение select для значения. Если указан <code>relation</code>, это ссылается на столбец в связанной таблице базы данных.</td></tr><tr><td><strong>valueFrom</strong></td><td>определяет атрибут модели для использования в качестве исходного значения. Если указан <code>relation</code>, это ссылается на атрибут отношения и выполняет жадную загрузку отношения.</td></tr><tr><td><strong>displayFrom</strong></td><td>определяет атрибут модели для использования в качестве отображаемого значения.</td></tr><tr><td><strong>relation</strong></td><td>определяет имя отношения модели как источник, используется с <code>select</code> или <code>valueFrom</code>.</td></tr><tr><td><strong>relationCount</strong></td><td>отображает количество связанных записей как значение столбца. Должно использоваться с опцией <code>relation</code>. По умолчанию: <code>false</code></td></tr><tr><td><strong>relationWith</strong></td><td>выполняет жадную загрузку указанного определения отношения с запросом списка. Полезно для улучшения производительности вложенных выборок столбцов.</td></tr><tr><td><strong>cssClass</strong></td><td>назначает CSS-класс контейнеру столбца.</td></tr><tr><td><strong>headCssClass</strong></td><td>назначает CSS-класс контейнеру заголовка столбца.</td></tr><tr><td><strong>width</strong></td><td>устанавливает ширину столбца, может быть указана в процентах (10%) или пикселях (50px). Может быть один столбец без указанной ширины, он растянется для заполнения доступного пространства.</td></tr><tr><td><strong>align</strong></td><td>определяет выравнивание столбца. Возможные значения: <code>left</code>, <code>right</code> и <code>center</code>.</td></tr><tr><td><strong>permissions</strong></td><td><a href="./../extend/backend/permissions.html">разрешения</a>, которые должен иметь текущий пользователь панели управления для использования столбца. Поддерживает строку для одного разрешения или массив разрешений, из которых достаточно одного для предоставления доступа.</td></tr><tr><td><strong>order</strong></td><td>числовой вес при определении порядка отображения, значение по умолчанию увеличивается на 100 пунктов за столбец.</td></tr><tr><td><strong>after</strong></td><td>поместить этот столбец после другого существующего столбца по имени, используя порядок отображения (+1).</td></tr><tr><td><strong>before</strong></td><td>поместить этот столбец перед другим существующим столбцом по имени, используя порядок отображения (-1).</td></tr><tr><td><strong>tooltip</strong></td><td>добавляет иконку с подсказкой после метки столбца. Подробнее см. ниже.</td></tr></tbody></table></div><h3 id="пользовательскии-выбор-значения"><a href="#пользовательскии-выбор-значения" class="header-anchor">#</a> Пользовательский выбор значения</h3><p>Можно изменить исходное и отображаемое значения для каждого столбца. Если вы хотите получить значение столбца из другого столбца, используйте опцию <code>valueFrom</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">other_name</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Something Great
    <span class="token key atrule">valueFrom</span><span class="token punctuation">:</span> name
</code></pre></div><p>Если вы хотите сохранить исходное значение столбца, но отображать другое значение из атрибута модели, используйте опцию <code>displayFrom</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">status_code</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Status
    <span class="token key atrule">displayFrom</span><span class="token punctuation">:</span> status_label
</code></pre></div><p>Это в основном применимо, когда используется <a href="./../extend/database/mutators.html">аксессор модели</a> для изменения отображаемого значения. Это полезно, когда вы хотите отображать одно значение, но сортировать и искать по другому.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getStatusLabelAttribute</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token function">title_case</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">status_code</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="вложенныи-выбор-столбцов"><a href="#вложенныи-выбор-столбцов" class="header-anchor">#</a> Вложенный выбор столбцов</h3><p>В некоторых случаях имеет смысл получать значение столбца из вложенной структуры данных, например, столбца <a href="./../extend/database/relations.html">отношения модели</a> или <a href="./../extend/system/models.html">jsonable-массива</a>. Следующий пример будет искать значение в PHP-эквиваленте <code>$record-&gt;content-&gt;title</code> или <code>$record-&gt;content[&#39;title&#39;]</code> соответственно.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code>content<span class="token punctuation">[</span>title<span class="token punctuation">]</span><span class="token punctuation">:</span>
    <span class="token key atrule">name</span><span class="token punctuation">:</span> Title
    <span class="token key atrule">sortable</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div><p>Единственный недостаток этого подхода — столбец не может использовать опции searchable или sortable. Чтобы сделать столбец доступным для поиска и по причинам производительности, рекомендуется дублировать его значение в локальной таблице базы данных с помощью <a href="./../extend/database/model.html">событий модели</a>. В качестве альтернативы вы можете использовать свойство <code>relation</code>, описанное далее.</p><h3 id="прямои-sql-выбор"><a href="#прямои-sql-выбор" class="header-anchor">#</a> Прямой SQL-выбор</h3><p>Свойство <code>select</code> позволяет создать столбец с использованием пользовательского выражения select. Здесь работает любое допустимое SQL-выражение SELECT.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">full_name</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Full Name
    <span class="token key atrule">select</span><span class="token punctuation">:</span> concat(first_name<span class="token punctuation">,</span> <span class="token string">&#39; &#39;</span><span class="token punctuation">,</span> last_name)
</code></pre></div><h3 id="выбор-связанного-столбца"><a href="#выбор-связанного-столбца" class="header-anchor">#</a> Выбор связанного столбца</h3><p>Свойство <code>relation</code> позволяет отображать связанные столбцы как часть запроса к базе данных, обеспечивая поиск и сортировку по этому столбцу. <code>relation</code> устанавливается в имя <a href="./../database/relations.html">отношения модели</a>. В следующем примере значение <strong>name</strong> будет преобразовано в атрибут name, найденный в связанной модели (например: <code>$model-&gt;name</code>).</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">group_name</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Group
    <span class="token key atrule">relation</span><span class="token punctuation">:</span> groups
    <span class="token key atrule">select</span><span class="token punctuation">:</span> name
</code></pre></div><p>Для отображения столбца с количеством связанных записей используйте свойство <code>relationCount</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">users_count</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Users
    <span class="token key atrule">type</span><span class="token punctuation">:</span> number
    <span class="token key atrule">relation</span><span class="token punctuation">:</span> users
    <span class="token key atrule">relationCount</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><div class="custom-block warning"><p>Будьте осторожны, не называйте отношения так же, как существующие столбцы базы данных. Например, использование имени <code>group_id</code> может нарушить отношение group из-за конфликта имён.</p></div><h3 id="подсказка"><a href="#подсказка" class="header-anchor">#</a> Подсказка</h3><p>Свойство <code>tooltip</code> улучшает столбцы списка, добавляя информационную иконку в заголовок столбца. При наведении на эту иконку отображается подсказка, предоставляющая дополнительный контекст или детали о столбце. Эта функция помогает предоставить пользователям руководство или пояснения для понимания содержимого столбца.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">count</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Count
    <span class="token key atrule">type</span><span class="token punctuation">:</span> number
    <span class="token key atrule">tooltip</span><span class="token punctuation">:</span> Number of users in the group
</code></pre></div><p>Помимо указания <code>title</code> подсказки, вы также можете задать <code>icon</code> (<a href="./../element/available-icons.html">доступные иконки</a>) и <code>placement</code> (<code>right</code>, <code>bottom</code>, <code>left</code>, значение по умолчанию — <code>top</code>) подсказки.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">count</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Count
    <span class="token key atrule">type</span><span class="token punctuation">:</span> number
    <span class="token key atrule">tooltip</span><span class="token punctuation">:</span>
        <span class="token key atrule">title</span><span class="token punctuation">:</span> Number of users in the group
        <span class="token key atrule">placement</span><span class="token punctuation">:</span> bottom
        <span class="token key atrule">icon</span><span class="token punctuation">:</span> icon<span class="token punctuation">-</span>users
</code></pre></div>`,28))])}const b=c(d,[["render",u]]);export{f as __pageData,b as default};
